insert into public.playbooks(id,version,content,review_status,sources)values('sourcing',2,$data${"steps": [{"id": "research", "instruction": "Research 8–12 supplier candidates", "source": "https://www.epicsourcing.co/epic-guide/how-to-buy-from-alibaba", "optional": false}, {"id": "verify", "instruction": "Require two independent verification signals before shortlist", "source": "https://www.epicsourcing.co/epic-guide/how-to-buy-from-alibaba", "optional": false}, {"id": "rfq", "instruction": "Send the identical approved component RFQ to at least eight eligible candidates unless founder accepts a dated exception", "source": "https://www.epicsourcing.co/epic-guide/how-to-buy-from-alibaba", "optional": false}, {"id": "compare", "instruction": "Compare 3–5 normalized quotes with eight performance criteria", "source": "https://www.epicsourcing.co/epic-guide/how-to-buy-from-alibaba", "optional": false}, {"id": "sample", "instruction": "Order paid samples from at least two suppliers unless a dated founder exception applies", "source": "https://www.epicsourcing.co/epic-guide/how-to-buy-from-alibaba", "optional": false}, {"id": "negotiate", "instruction": "Check exact current mandate bounds; escalate differences", "source": "https://www.epicsourcing.co/epic-guide/how-to-buy-from-alibaba", "optional": false}, {"id": "proforma", "instruction": "Freeze approved specification, price, currency and Incoterm in a proforma before deposit", "source": "https://www.epicsourcing.co/epic-guide/how-to-buy-from-alibaba", "optional": false}, {"id": "inspection", "instruction": "Book pre-shipment inspection; require clean report or dated founder risk acceptance before balance", "source": "https://www.epicsourcing.co/epic-guide/how-to-buy-from-alibaba", "optional": false}], "defaults": {"maxCandidates": 12, "minimumCandidates": 8, "shortlistMinimum": 3, "shortlistMaximum": 5, "sampleSupplierMinimum": 2}, "reviewRequired": true, "reviewNote": "Implementation defaults from BRD; practitioner/doma